/**
 * Input Box Studio presets: 32 interactive text fields, each a native InputBox widget with
 * options.motion = preset id. A preset is a frame (box, underline, cells...), a label behaviour
 * and a set of effects; one shared renderer (kit.ts) draws them all, so every effect is an
 * option the user can switch and tune on any field.
 */
export type InputFrame = 'box' | 'underline' | 'pill' | 'glass' | 'cells' | 'capsule' | 'dashes' | 'flap' | 'search' | 'area' | 'dual';
export type InputLabel = 'notch' | 'tab' | 'badge' | 'icon' | 'inside' | 'above' | 'none';
export type InputFx = 'bloom' | 'rail' | 'magnet' | 'orbit' | 'breathe' | 'dualline' | 'liquid' | 'prism' | 'shake' | 'squish' | 'elastic' | 'confetti' | 'bleed' | 'flycaret' | 'scramble' | 'meter' | 'wave' | 'eye' | 'steppers' | 'tray' | 'drawer' | 'prefix' | 'check' | 'grow';
export type InputKind = 'text' | 'email' | 'password' | 'number' | 'code' | 'currency' | 'search' | 'range';
export interface InputPreset {
    id: string;
    num: number;
    cat: number;
    name: string;
    desc: string;
    tags: string[];
    W: number;
    H: number;
    frame: InputFrame;
    label: InputLabel;
    fx: InputFx[];
    kind: InputKind;
    /** cells for code/segmented frames */
    cells?: number;
    label_: string;
    placeholder: string;
    helper?: string;
    prefix?: string;
    /** text the studio demo types */
    demo: string;
    /** validation the demo and Enter use */
    validate?: 'none' | 'required' | 'email' | 'min' | 'number' | 'strong';
    /** stacked group (Sliding Underline Rail inserts three fields) */
    group?: string[];
    /** autocomplete rows (drawer) */
    suggestions?: string[];
    maxLength?: number;
}
export declare const INPUT_CATEGORIES: {
    id: number;
    name: string;
    blurb: string;
}[];
export declare const INPUT_PRESETS: InputPreset[];
export declare function inputPresetById(id: string | undefined): InputPreset | undefined;
